import java.util.Arrays;
import java.util.List;

public final class KMPSearchTest {

    private KMPSearchTest() {
    }

    public static void main(String[] args) {
        assertMatches("aaba", "aabaacaadaabaaba", indexes(0, 9, 12));
        assertMatches("aa", "aaaa", indexes(0, 1, 2));
        assertMatches("a", "banana", indexes(1, 3, 5));
        assertMatches("abc", "def", indexes());
        assertMatches("abcdef", "abc", indexes());
        assertMatches("abc", "", indexes());
        assertMatches("", "", indexes(0));
        assertMatches("", "abc", indexes(0, 1, 2, 3));
        assertMatches(new StringBuilder("aba"), new StringBuilder("ababa"), indexes(0, 2));

        assertRejects("null pattern", () -> KMPSearch.search(null, "abc"));
        assertRejects("null text", () -> KMPSearch.search("abc", null));
    }

    private static void assertMatches(CharSequence pattern, CharSequence text, List<Integer> expected) {
        List<Integer> actual = KMPSearch.search(pattern, text);
        if (!actual.equals(expected)) {
            String message = "Expected matches " + expected + " for pattern '" + pattern + "' in text '"
                    + text + "', but got " + actual + ".";
            throw new AssertionError(message);
        }
    }

    private static List<Integer> indexes(Integer... values) {
        return Arrays.asList(values);
    }

    private static void assertRejects(String scenario, Runnable action) {
        boolean rejected = false;
        try {
            action.run();
        } catch (IllegalArgumentException expected) {
            rejected = true;
        }

        if (!rejected) {
            throw new AssertionError("Expected " + scenario + " to be rejected.");
        }
    }
}

import java.util.List;

public final class KmpPatternSearchingDemo {
    private static final String DEFAULT_TEXT = "aabaacaadaabaaba";
    private static final String DEFAULT_PATTERN = "aaba";

    private KmpPatternSearchingDemo() {
    }

    public static void main(String[] args) {
        List<Integer> matches = KMPSearch.search(DEFAULT_PATTERN, DEFAULT_TEXT);

        System.out.println(formatMatches(matches));
    }

    private static String formatMatches(List<Integer> matches) {
        StringBuilder output = new StringBuilder();
        for (int index = 0; index < matches.size(); index++) {
            if (index > 0) {
                output.append(' ');
            }
            output.append(matches.get(index));
        }
        return output.toString();
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class KMPSearch {

    private KMPSearch() {
    }

    public static void main(String[] args) {
        KmpPatternSearchingDemo.main(args);
    }

    /**
     * Returns every zero-based position where {@code pattern} appears in {@code text}.
     * Empty patterns match every insertion point from {@code 0} through {@code text.length()}.
     */
    public static List<Integer> search(CharSequence pattern, CharSequence text) {
        validateInputs(pattern, text);

        if (pattern.length() == 0) {
            return allInsertionPoints(text.length());
        }

        if (pattern.length() > text.length()) {
            return Collections.emptyList();
        }

        return findMatches(pattern, text, buildLps(pattern));
    }

    private static List<Integer> findMatches(CharSequence pattern, CharSequence text, int[] lps) {
        List<Integer> matches = new ArrayList<>();
        int textIndex = 0;
        int patternIndex = 0;

        while (textIndex < text.length()) {
            if (text.charAt(textIndex) == pattern.charAt(patternIndex)) {
                textIndex++;
                patternIndex++;

                if (patternIndex == pattern.length()) {
                    matches.add(textIndex - patternIndex);
                    patternIndex = lps[patternIndex - 1];
                }
            } else if (patternIndex > 0) {
                patternIndex = lps[patternIndex - 1];
            } else {
                textIndex++;
            }
        }

        return matches;
    }

    private static int[] buildLps(CharSequence pattern) {
        int[] lps = new int[pattern.length()];
        int prefixLength = 0;
        int index = 1;

        while (index < pattern.length()) {
            if (pattern.charAt(index) == pattern.charAt(prefixLength)) {
                lps[index] = ++prefixLength;
                index++;
            } else if (prefixLength > 0) {
                prefixLength = lps[prefixLength - 1];
            } else {
                lps[index] = 0;
                index++;
            }
        }

        return lps;
    }

    private static List<Integer> allInsertionPoints(int textLength) {
        List<Integer> matches = new ArrayList<>();
        for (int index = 0; index <= textLength; index++) {
            matches.add(index);
        }
        return matches;
    }

    private static void validateInputs(CharSequence pattern, CharSequence text) {
        if (pattern == null || text == null) {
            throw new IllegalArgumentException("Pattern and text must not be null.");
        }
    }
}

final class kmp_pattern_searching {

    private kmp_pattern_searching() {
    }

    public static void main(String[] args) {
        KmpPatternSearchingDemo.main(args);
    }
}

